import React, { useContext } from "react";
import { makeStyles } from "@material-ui/core/styles";
import Fade from "react-reveal/Fade";

import { ThemeContext } from "../../contexts/ThemeContext";

import eduImgWhite from "../../assets/svg/education/eduImgWhite.svg";
import eduImgBlack from "../../assets/svg/education/eduImgBlack.svg";
import "./Education.css";

function EducationCard({
  id,
  institution,
  course,
  startYear,
  endYear,
  notes,
  logo,
  logoAlt,
}) {
  const { theme } = useContext(ThemeContext);

  const useStyles = makeStyles((t) => ({
    educationCard: {
      backgroundColor: theme.primary30,
      "&:hover": {
        backgroundColor: theme.primary50,
      },
    },
  }));

  const classes = useStyles();

  const yearLabel =
    startYear || endYear
      ? `${startYear}${endYear ? ` to ${endYear}` : ""}`
      : "";

  return (
    <Fade bottom>
      <div key={id} className={`education-card ${classes.educationCard}`}>
        <div
          className={`educard-img${logo ? " educard-img--logo" : ""}`}
          style={{ backgroundColor: logo ? "#ffffff" : theme.primary }}
        >
          <img
            src={logo || (theme.type === "light" ? eduImgBlack : eduImgWhite)}
            alt={logo ? logoAlt || "" : ""}
          />
        </div>
        <div className="education-details">
          {yearLabel && <h6 style={{ color: theme.primary }}>{yearLabel}</h6>}
          <h4 style={{ color: theme.tertiary }}>{course}</h4>
          <h5 style={{ color: theme.tertiary80 }}>{institution}</h5>
          {notes && (
            <p className="education-notes" style={{ color: theme.tertiary80 }}>
              {notes}
            </p>
          )}
        </div>
      </div>
    </Fade>
  );
}

export default EducationCard;
