import React, { useContext } from "react";
import { makeStyles } from "@material-ui/core/styles";
import Fade from "react-reveal/Fade";

import { ThemeContext } from "../../contexts/ThemeContext";

import expImgWhite from "../../assets/svg/experience/expImgWhite.svg";
import expImgBlack from "../../assets/svg/experience/expImgBlack.svg";

import "./Experience.css";

function ExperienceCard({
  id,
  company,
  jobtitle,
  startYear,
  endYear,
  roles,
  bullets,
}) {
  const { theme } = useContext(ThemeContext);

  const useStyles = makeStyles((t) => ({
    experienceCard: {
      backgroundColor: theme.primary30,
      "&:hover": {
        backgroundColor: theme.primary50,
      },
    },
  }));

  const classes = useStyles();

  return (
    <Fade bottom>
      <div key={id} className={`experience-card ${classes.experienceCard}`}>
        <div className="expcard-img" style={{ backgroundColor: theme.primary }}>
          <img
            src={theme.type === "light" ? expImgBlack : expImgWhite}
            alt=""
          />
        </div>
        <div className="experience-details">
          <h6 style={{ color: theme.primary }}>
            {startYear} to {endYear}
          </h6>
          <h4 style={{ color: theme.tertiary }}>{company}</h4>
          {roles && roles.length > 0 ? (
            <ul className="experience-roles">
              {roles.map((role) => (
                <li key={role.title} style={{ color: theme.tertiary80 }}>
                  {role.title} ({role.dates})
                </li>
              ))}
            </ul>
          ) : (
            <h5 style={{ color: theme.tertiary80 }}>{jobtitle}</h5>
          )}
          {bullets && bullets.length > 0 && (
            <ul className="experience-bullets">
              {bullets.map((bullet) => (
                <li key={bullet} style={{ color: theme.tertiary80 }}>
                  {bullet}
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </Fade>
  );
}

export default ExperienceCard;
